      sprite.x = objEvent.initialCoords.x;
      sprite.y = objEvent.initialCoords.y;
      SetObjectSubpriorityByElevation(objEvent.previousElevation, sprite, 1);
      rt.gba.oam[sprite.oamIndex].priority = ElevationToPriority(objEvent.previousElevation);

      if (linkPlayerObjEvent.movementMode == MOVEMENT_MODE_FREE)
          rt.StartSpriteAnim(sprite.spriteId, GetFaceDirectionAnimNum(linkDirection(objEvent)));
      else
          rt.StartSpriteAnim(sprite.spriteId, GetMoveDirectionAnimNum(linkDirection(objEvent)));

      UpdateObjectEventSpriteInvisibility(sprite, false);
      if (objEvent.triggerGroundEffectsOnMove)
      {
          sprite.invisible = ((sprite.data[7] & 4) >> 2);
          sprite.data[7]++;
      }
